(() => {
  const T = window.THREE;
  const canvas = document.getElementById("cassette-canvas");
  const stage = document.getElementById("model-stage");
  if (!T || !canvas || !stage) return;

  let renderer, scene, camera;
  try {
    renderer = new T.WebGLRenderer({
      canvas,
      alpha: true,
      antialias: true,
      powerPreference: "high-performance",
    });
  } catch (error) {
    console.warn("3D renderer unavailable", error);
    stage.classList.add("is-fallback");
    return;
  }

  renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
  renderer.setSize(stage.clientWidth, stage.clientHeight, false);
  renderer.outputEncoding = T.sRGBEncoding;
  renderer.toneMapping = T.ACESFilmicToneMapping;
  renderer.toneMappingExposure = 1.32;
  renderer.shadowMap.enabled = true;
  renderer.shadowMap.type = T.PCFSoftShadowMap;

  scene = new T.Scene();
  camera = new T.PerspectiveCamera(
    36,
    stage.clientWidth / Math.max(stage.clientHeight, 1),
    0.1,
    80
  );
  camera.position.set(0, 0.12, 8.2);

  /* ── Lighting Rig ── */
  scene.add(new T.AmbientLight(0xffffff, 0.75));
  scene.add(new T.HemisphereLight(0xffe8f8, 0x080614, 1.25));

  const key = new T.DirectionalLight(0xffffff, 4.6);
  key.position.set(-4.0, 7.0, 8.5);
  scene.add(key);

  const fill = new T.DirectionalLight(0xffd5ec, 2.6);
  fill.position.set(6.0, 2.0, 4.5);
  scene.add(fill);

  const rim = new T.DirectionalLight(0xa5c4ff, 3.4);
  rim.position.set(0.0, -3.0, -6.5);
  scene.add(rim);

  const top = new T.DirectionalLight(0xffffff, 1.8);
  top.position.set(0.0, 9.0, 2.0);
  scene.add(top);

  // Dynamic point lights for iridescent reflection
  const pinkPt = new T.PointLight(0xff3399, 7.0, 14, 2);
  const purplePt = new T.PointLight(0x7733ff, 5.0, 12, 2);
  const cyanPt = new T.PointLight(0x22ccff, 4.5, 10, 2);
  scene.add(pinkPt, purplePt, cyanPt);

  /* ── Shared Textures & Materials ── */
  const labelTex = new T.TextureLoader().load(
    "data:image/webp;base64,"
  );
  labelTex.encoding = T.sRGBEncoding;

  const holoVert = `
    varying vec3 vNormal;
    varying vec3 vViewDir;
    varying vec2 vUv;
    void main() {
      vUv = uv;
      vec4 worldPos = modelMatrix * vec4(position, 1.0);
      vNormal = normalize(normalMatrix * normal);
      vViewDir = normalize(cameraPosition - worldPos.xyz);
      gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
    }
  `;

  const holoFrag = `
    precision highp float;
    uniform sampler2D map;
    uniform float time;
    uniform float hueShift;
    varying vec3 vNormal;
    varying vec3 vViewDir;
    varying vec2 vUv;

    vec3 hsv2rgb(vec3 c) {
      vec4 K = vec4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);
      vec3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
      return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
    }

    float hash(vec2 p) {
      return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
    }

    float sparkle(vec2 uv, float t) {
      const float GRID = 32.0;
      vec2 id = floor(uv * GRID);
      float rng = hash(id);
      float pulse = pow(sin(t * (3.0 + rng * 7.0) + rng * 6.28318) * 0.5 + 0.5, 4.0);
      float sz = 0.05 + rng * 0.08;
      vec2 cell = fract(uv * GRID) - 0.5;
      return pow(max(0.0, 1.0 - length(cell) / sz), 5.0) * pulse;
    }

    void main() {
      vec4 baseColor = texture2D(map, vUv);
      if (baseColor.a < 0.08) discard;

      vec3 N = normalize(vNormal);
      vec3 V = normalize(vViewDir);
      float NdotV = max(0.0, dot(N, V));
      float fresnel = pow(1.0 - NdotV, 1.25);

      // Holographic hue wash with per-cassette hueShift
      float wave = sin(time * 0.8 + vUv.y * 5.0 + vUv.x * 2.5) * 0.08;
      float tiltFactor = clamp(fresnel * 1.2 + wave, 0.0, 1.0);
      float hue = 0.96 + hueShift - tiltFactor * 0.42;

      float grating = sin((vUv.x * 3.2 - vUv.y * 4.0) * 36.0 + (1.0 - NdotV) * 14.0 + time * 1.6);
      float foilShine = pow(max(0.0, grating), 8.0) * 0.65;

      vec3 holoColor = hsv2rgb(vec3(fract(hue), 0.78 + fresnel * 0.2, 1.0));
      vec3 foilColor = mix(vec3(1.0, 0.8, 0.95), vec3(0.6, 0.85, 1.0), sin(vUv.y * 6.0 + time) * 0.5 + 0.5);
      holoColor += foilShine * foilColor;

      float sp = sparkle(vUv, time);
      vec3 starColor = mix(vec3(1.0, 0.9, 1.0), vec3(0.8, 0.95, 1.0), hash(vUv * 10.0));
      holoColor += sp * starColor * 1.2;

      float luminance = dot(baseColor.rgb, vec3(0.299, 0.587, 0.114));
      float holoStrength = mix(0.40, 0.95, luminance) * (0.45 + fresnel * 0.75);
      vec3 result = mix(baseColor.rgb, holoColor, holoStrength);

      vec3 L = normalize(vec3(-0.3, 0.7, 0.9));
      vec3 H = normalize(L + V);
      float spec = pow(max(0.0, dot(N, H)), 64.0) * 0.75;
      result += spec * vec3(1.0, 0.95, 1.0);

      gl_FragColor = vec4(result, baseColor.a);
    }
  `;

  function createHoloMaterial(hueShift = 0.0) {
    return new T.ShaderMaterial({
      uniforms: {
        map: { value: labelTex },
        time: { value: 0.0 },
        hueShift: { value: hueShift },
      },
      vertexShader: holoVert,
      fragmentShader: holoFrag,
      transparent: true,
      side: T.FrontSide,
    });
  }

  /* Physical materials */
  function createPinkAcrylicMat(colorHex = 0xff338f) {
    return new T.MeshPhysicalMaterial({
      color: colorHex,
      roughness: 0.045,
      metalness: 0.0,
      transmission: 0.84,
      thickness: 0.42,
      ior: 1.492,
      clearcoat: 1.0,
      clearcoatRoughness: 0.02,
      transparent: true,
      opacity: 0.92,
      envMapIntensity: 1.8,
      side: T.DoubleSide,
    });
  }

  const tapeSpoolMat = new T.MeshPhysicalMaterial({
    color: 0x1a0905,
    roughness: 0.48,
    metalness: 0.08,
    clearcoat: 0.35,
    clearcoatRoughness: 0.25,
  });

  const tapeRibbonMat = new T.MeshPhysicalMaterial({
    color: 0x180703,
    roughness: 0.30,
    metalness: 0.12,
    clearcoat: 0.6,
    clearcoatRoughness: 0.15,
    side: T.DoubleSide,
  });

  const chromeScrewMat = new T.MeshPhysicalMaterial({
    color: 0xe8e6f0,
    roughness: 0.06,
    metalness: 0.98,
    clearcoat: 1.0,
    clearcoatRoughness: 0.02,
    envMapIntensity: 2.2,
  });

  const bronzeRollerMat = new T.MeshPhysicalMaterial({
    color: 0x1f1f22,
    roughness: 0.18,
    metalness: 0.75,
    clearcoat: 0.8,
  });

  const copperSpringMat = new T.MeshPhysicalMaterial({
    color: 0xb87333,
    roughness: 0.25,
    metalness: 0.90,
  });

  // Soft Ground Shadow texture
  const shadowCanvas = document.createElement("canvas");
  shadowCanvas.width = 256;
  shadowCanvas.height = 256;
  const sCtx = shadowCanvas.getContext("2d");
  const sGrad = sCtx.createRadialGradient(128, 128, 6, 128, 128, 120);
  sGrad.addColorStop(0, "rgba(235, 100, 170, 0.26)");
  sGrad.addColorStop(0.4, "rgba(120, 40, 95, 0.14)");
  sGrad.addColorStop(0.75, "rgba(30, 20, 40, 0.04)");
  sGrad.addColorStop(1, "rgba(0, 0, 0, 0)");
  sCtx.fillStyle = sGrad;
  sCtx.fillRect(0, 0, 256, 256);
  const shadowTex = new T.CanvasTexture(shadowCanvas);

  function createRoundedShape(w, h, r) {
    const s = new T.Shape();
    const x0 = -w / 2, y0 = -h / 2;
    s.moveTo(x0 + r, y0);
    s.lineTo(x0 + w - r, y0);
    s.quadraticCurveTo(x0 + w, y0, x0 + w, y0 + r);
    s.lineTo(x0 + w, y0 + h - r);
    s.quadraticCurveTo(x0 + w, y0 + h, x0 + w - r, y0 + h);
    s.lineTo(x0 + r, y0 + h);
    s.quadraticCurveTo(x0, y0 + h, x0, y0 + h - r);
    s.lineTo(x0, y0 + r);
    s.quadraticCurveTo(x0, y0, x0 + r, y0);
    return s;
  }

  const cW = 3.82, cH = 2.44, cD = 0.44;
  const shellDepth = cD / 2;

  // Shared geometry
  const shellShape = createRoundedShape(cW, cH, 0.15);
  const shellGeo = new T.ExtrudeGeometry(shellShape, {
    depth: shellDepth - 0.02,
    bevelEnabled: true,
    bevelSegments: 3,
    steps: 1,
    bevelSize: 0.016,
    bevelThickness: 0.016,
  });
  shellGeo.center();

  const innerWallShape = createRoundedShape(cW - 0.08, cH - 0.08, 0.12);
  const innerWallHole = createRoundedShape(cW - 0.22, cH - 0.22, 0.08);
  innerWallShape.holes.push(new T.Path(innerWallHole.getPoints().reverse()));
  const innerWallGeo = new T.ExtrudeGeometry(innerWallShape, {
    depth: cD - 0.04,
    bevelEnabled: false,
  });
  innerWallGeo.center();

  const trapShape = new T.Shape();
  const tTopW = 2.05, tBotW = 1.68, tH = 0.54;
  trapShape.moveTo(-tTopW / 2, 0);
  trapShape.lineTo(tTopW / 2, 0);
  trapShape.lineTo(tBotW / 2, -tH);
  trapShape.lineTo(-tBotW / 2, -tH);
  trapShape.closePath();
  const trapGeo = new T.ExtrudeGeometry(trapShape, {
    depth: cD + 0.06,
    bevelEnabled: true,
    bevelSegments: 2,
    steps: 1,
    bevelSize: 0.015,
    bevelThickness: 0.015,
  });
  trapGeo.center();

  /* ── 3 Cassette Models Data ── */
  const trackUrls = [
    "https://www.youtube.com/watch?v=KAY71h_2T0k&list=RDKAY71h_2T0k&start_radio=1",
    "https://www.youtube.com/watch?v=YWN81V7ojOE&list=RDYWN81V7ojOE&start_radio=1",
    "https://www.youtube.com/watch?v=OBd0m-turW8&list=RDOBd0m-turW8&start_radio=1",
  ];

  const models = [];
  const badges = document.querySelectorAll(".vhs-track-badge");

  function playTrack(index) {
    const url = trackUrls[index] || trackUrls[0];
    window.open(url, "_blank", "noopener,noreferrer");
  }

  // Allow clicking on DOM badges as well
  badges.forEach((b, i) => {
    b.addEventListener("click", () => playTrack(i));
  });

  const colorVariants = [
    { shell: 0xff338f, hueShift: 0.00 }, // Pink (VHS 01)
    { shell: 0xaa33ff, hueShift: 0.15 }, // Violet (VHS 02)
    { shell: 0x2288ff, hueShift: 0.32 }, // Blue-Cyan (VHS 03)
  ];

  function buildSingleCassette(index) {
    const root = new T.Group();
    scene.add(root);

    const variant = colorVariants[index];
    const acrylicMat = createPinkAcrylicMat(variant.shell);
    const holoMat = createHoloMaterial(variant.hueShift);

    // Front & Back Shells
    const front = new T.Mesh(shellGeo, acrylicMat);
    front.position.z = shellDepth / 2;
    root.add(front);

    const back = new T.Mesh(shellGeo, acrylicMat);
    back.position.z = -shellDepth / 2;
    root.add(back);

    // Inner rim
    const inner = new T.Mesh(innerWallGeo, acrylicMat);
    root.add(inner);

    // Bottom read head
    const trap = new T.Mesh(trapGeo, acrylicMat);
    trap.position.set(0, -cH / 2 + tH / 2 - 0.04, 0);
    root.add(trap);

    // Holographic Label Front & Back
    const labelW = 3.48, labelH = 1.46;
    const labelMesh = new T.Mesh(
      new T.PlaneGeometry(labelW, labelH),
      holoMat
    );
    labelMesh.position.set(0, 0.15, shellDepth + 0.018);
    root.add(labelMesh);

    const backLabelMesh = new T.Mesh(
      new T.PlaneGeometry(labelW, labelH),
      holoMat
    );
    backLabelMesh.rotation.y = Math.PI;
    backLabelMesh.position.set(0, 0.15, -shellDepth - 0.018);
    root.add(backLabelMesh);

    // Tape Reels (Rewind)
    const reelGroup = new T.Group();
    root.add(reelGroup);
    const reelCenterDist = 0.81;
    const reelY = 0.15;

    function buildReel(tapeRadius) {
      const reel = new T.Group();
      const spoolGeo = new T.CylinderGeometry(tapeRadius, tapeRadius, 0.125, 48);
      spoolGeo.rotateX(Math.PI / 2);
      reel.add(new T.Mesh(spoolGeo, tapeSpoolMat));

      const hubR = 0.245;
      const hubBodyGeo = new T.CylinderGeometry(hubR, hubR, 0.138, 36);
      hubBodyGeo.rotateX(Math.PI / 2);
      reel.add(new T.Mesh(hubBodyGeo, new T.MeshPhysicalMaterial({
        color: 0xf5f5fa,
        roughness: 0.28,
        metalness: 0.05,
        clearcoat: 0.5,
      })));

      const teethCount = 6;
      const toothGeo = new T.BoxGeometry(0.044, 0.068, 0.144);
      const toothMat = new T.MeshPhysicalMaterial({
        color: 0x111115,
        roughness: 0.3,
        metalness: 0.2,
      });
      for (let i = 0; i < teethCount; i++) {
        const angle = (i / teethCount) * Math.PI * 2;
        const tooth = new T.Mesh(toothGeo, toothMat);
        const r = 0.165;
        tooth.position.set(Math.cos(angle) * r, Math.sin(angle) * r, 0);
        tooth.rotation.z = angle;
        reel.add(tooth);
      }

      const holeGeo = new T.CylinderGeometry(0.125, 0.125, 0.150, 24);
      holeGeo.rotateX(Math.PI / 2);
      reel.add(new T.Mesh(holeGeo, new T.MeshBasicMaterial({ color: 0xffffff })));
      return reel;
    }

    const reelLeft = buildReel(0.53);
    reelLeft.position.set(-reelCenterDist, reelY, 0);
    reelGroup.add(reelLeft);

    const reelRight = buildReel(0.28);
    reelRight.position.set(reelCenterDist, reelY, 0);
    reelGroup.add(reelRight);

    // Ribbon path
    const ribbonCurve = new T.CatmullRomCurve3([
      new T.Vector3(-reelCenterDist, reelY - 0.53, 0),
      new T.Vector3(-0.95, -0.65, 0),
      new T.Vector3(-0.72, -0.92, 0),
      new T.Vector3(-0.35, -0.98, 0),
      new T.Vector3(0.00, -0.99, 0),
      new T.Vector3(0.35, -0.98, 0),
      new T.Vector3(0.72, -0.92, 0),
      new T.Vector3(0.95, -0.65, 0),
      new T.Vector3(reelCenterDist, reelY - 0.28, 0),
    ]);
    root.add(new T.Mesh(
      new T.TubeGeometry(ribbonCurve, 40, 0.024, 5, false),
      tapeRibbonMat
    ));

    // Rollers & Hardware
    [-0.72, 0.72].forEach((x) => {
      const rollerGeo = new T.CylinderGeometry(0.088, 0.088, 0.14, 20);
      rollerGeo.rotateX(Math.PI / 2);
      const roller = new T.Mesh(rollerGeo, bronzeRollerMat);
      roller.position.set(x, -0.92, 0);
      root.add(roller);

      const pinGeo = new T.CylinderGeometry(0.032, 0.032, cD + 0.02, 12);
      pinGeo.rotateX(Math.PI / 2);
      const pin = new T.Mesh(pinGeo, acrylicMat);
      pin.position.set(x, -0.92, 0);
      root.add(pin);
    });

    const shieldGeo = new T.BoxGeometry(0.48, 0.18, 0.12);
    const shield = new T.Mesh(shieldGeo, new T.MeshPhysicalMaterial({
      color: 0x44444c,
      roughness: 0.22,
      metalness: 0.92,
    }));
    shield.position.set(0, -0.94, 0);
    root.add(shield);

    const spring = new T.Mesh(new T.BoxGeometry(0.26, 0.03, 0.08), copperSpringMat);
    spring.position.set(0, -0.99, 0);
    root.add(spring);

    const felt = new T.Mesh(new T.BoxGeometry(0.12, 0.04, 0.06), new T.MeshStandardMaterial({
      color: 0xddb888,
      roughness: 0.95,
    }));
    felt.position.set(0, -1.02, 0);
    root.add(felt);

    // 5 Screws
    const screwPositions = [
      [-cW / 2 + 0.18, cH / 2 - 0.18],
      [cW / 2 - 0.18, cH / 2 - 0.18],
      [-cW / 2 + 0.18, -cH / 2 + 0.18],
      [cW / 2 - 0.18, -cH / 2 + 0.18],
      [0.00, cH / 2 - 0.18],
    ];

    screwPositions.forEach(([x, y]) => {
      const screwHeadGeo = new T.CylinderGeometry(0.065, 0.065, 0.035, 16);
      screwHeadGeo.rotateX(Math.PI / 2);
      const sFront = new T.Mesh(screwHeadGeo, chromeScrewMat);
      sFront.position.set(x, y, shellDepth + 0.012);
      root.add(sFront);

      const sBack = sFront.clone();
      sBack.position.z = -shellDepth - 0.012;
      root.add(sBack);

      const sleeveGeo = new T.CylinderGeometry(0.042, 0.042, cD, 12);
      sleeveGeo.rotateX(Math.PI / 2);
      const sleeve = new T.Mesh(sleeveGeo, acrylicMat);
      sleeve.position.set(x, y, 0);
      root.add(sleeve);
    });

    // Individual contact shadow
    const shadowMesh = new T.Mesh(
      new T.PlaneGeometry(3.6, 2.2),
      new T.MeshBasicMaterial({
        map: shadowTex,
        transparent: true,
        depthWrite: false,
      })
    );
    shadowMesh.rotation.x = -Math.PI / 2;
    shadowMesh.position.y = -1.90;
    scene.add(shadowMesh);

    const modelObj = {
      root,
      index,
      holoMat,
      reelLeft,
      reelRight,
      shadowMesh,
      homeX: 0,
      homeY: 0,
      scale: 0.58,
      spinSpeed: 0.005 + index * 0.0012,
      phase: index * 2.15,
      rotX: 0,
      rotY: 0,
      velX: 0,
      velY: 0,
      hover: false,
    };

    root.traverse((o) => {
      o.userData.tapeModel = modelObj;
    });

    models.push(modelObj);
    return modelObj;
  }

  // Build the 3 cassettes
  for (let i = 0; i < 3; i++) {
    buildSingleCassette(i);
  }

  /* ── Responsive Positioning & Scaling ── */
  function updateLayout() {
    const w = stage.clientWidth;
    const h = stage.clientHeight;
    if (!w || !h) return;

    camera.aspect = w / h;
    camera.updateProjectionMatrix();
    renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
    renderer.setSize(w, h, false);

    const portrait = w / h < 1.3;
    // Spacing between the 3 cassettes
    models.forEach((m, i) => {
      m.homeX = portrait ? 0 : (i - 1) * 2.75;
      m.homeY = portrait ? (1 - i) * 1.55 : 0.08;
      // Reduced model scale (0.58 down from 0.92) as requested!
      m.scale = portrait ? 0.44 : 0.58;
      m.shadowMesh.position.x = m.homeX;
      m.shadowMesh.position.y = portrait ? m.homeY - 1.15 : -1.85;
      m.shadowMesh.scale.setScalar(m.scale / 0.58);
    });
  }

  window.addEventListener("resize", updateLayout, { passive: true });
  new ResizeObserver(updateLayout).observe(stage);
  updateLayout();

  /* ── Raycaster & Interaction ── */
  const raycaster = new T.Raycaster();
  const mouse = new T.Vector2();

  function pickCassette(clientX, clientY) {
    const rect = canvas.getBoundingClientRect();
    mouse.x = ((clientX - rect.left) / rect.width) * 2 - 1;
    mouse.y = -((clientY - rect.top) / rect.height) * 2 + 1;
    raycaster.setFromCamera(mouse, camera);

    const roots = models.map((m) => m.root);
    const hits = raycaster.intersectObjects(roots, true);
    if (hits.length > 0) {
      let cur = hits[0].object;
      while (cur) {
        if (cur.userData && cur.userData.tapeModel) {
          return cur.userData.tapeModel;
        }
        cur = cur.parent;
      }
    }
    return null;
  }

  let activeModel = null;
  let downX = 0, downY = 0;
  let hasMoved = false;

  canvas.addEventListener("pointerdown", (e) => {
    const picked = pickCassette(e.clientX, e.clientY);
    activeModel = picked || models[1];
    downX = e.clientX;
    downY = e.clientY;
    hasMoved = false;
    canvas.setPointerCapture?.(e.pointerId);
  });

  canvas.addEventListener("pointermove", (e) => {
    const dx = e.clientX - downX;
    const dy = e.clientY - downY;
    if (Math.hypot(dx, dy) > 5) hasMoved = true;

    if (activeModel && e.buttons > 0) {
      activeModel.velY = (e.clientX - downX) * 0.009;
      activeModel.velX = (e.clientY - downY) * 0.007;
      activeModel.rotY += activeModel.velY;
      activeModel.rotX = Math.max(-1.25, Math.min(1.25, activeModel.rotX + activeModel.velX));
      downX = e.clientX;
      downY = e.clientY;
    } else {
      // Hover detection
      const hovered = pickCassette(e.clientX, e.clientY);
      canvas.style.cursor = hovered ? "pointer" : "grab";
      models.forEach((m, idx) => {
        m.hover = m === hovered;
        if (badges[idx]) {
          badges[idx].classList.toggle("is-active", m.hover);
        }
      });
    }
  });

  canvas.addEventListener("pointerup", (e) => {
    if (!hasMoved && activeModel) {
      // It's a clean click -> Open the song link!
      playTrack(activeModel.index);
    }
    activeModel = null;
  });

  canvas.addEventListener("pointercancel", () => {
    activeModel = null;
  });

  canvas.addEventListener("pointerleave", () => {
    activeModel = null;
    canvas.style.cursor = "grab";
    models.forEach((m, idx) => {
      m.hover = false;
      if (badges[idx]) badges[idx].classList.remove("is-active");
    });
  });

  /* ── Animation Loop ── */
  const clock = new T.Clock();
  const baseReelSpeed = 0.038;
  let frameId = 0;

  function animate() {
    frameId = requestAnimationFrame(animate);
    if (document.hidden) return;
    const t = clock.getElapsedTime();
    const dt = Math.min(clock.getDelta(), 0.05);

    models.forEach((m, i) => {
      // Auto-rotation & inertia damping
      if (activeModel !== m) {
        m.rotY += m.spinSpeed;
      }
      m.velX *= 0.93;
      m.velY *= 0.93;
      m.rotY += m.velY;
      m.rotX = Math.max(-1.25, Math.min(1.25, m.rotX + m.velX));

      // Gentle floating & tilt oscillation
      const tiltWobble = Math.sin(t * 0.65 + m.phase) * 0.18;
      m.root.rotation.y = m.rotY;
      m.root.rotation.x = m.rotX + tiltWobble;

      // Smooth hover elevation
      const targetY = m.homeY + (m.hover ? 0.14 : 0.0) + Math.sin(t * 1.2 + m.phase) * 0.035;
      m.root.position.set(m.homeX, targetY, 0);
      m.root.scale.setScalar(m.scale);

      // Spinning reels (rewind)
      m.reelLeft.rotation.z += baseReelSpeed;
      m.reelRight.rotation.z += baseReelSpeed * 1.89;

      // Update holographic shader time
      m.holoMat.uniforms.time.value = t;
    });

    // Animate accent point lights
    pinkPt.position.set(
      Math.sin(t * 0.7) * 5.0,
      Math.cos(t * 0.5) * 3.0 + 1.0,
      Math.cos(t * 0.7) * 4.0 + 3.0
    );
    purplePt.position.set(
      Math.cos(t * 0.6) * 5.5,
      Math.sin(t * 0.8) * 2.5 - 0.5,
      Math.sin(t * 0.6) * 3.5 + 3.5
    );
    cyanPt.position.set(
      Math.sin(t * 0.9 + 2.0) * 4.0,
      Math.cos(t * 0.7) * 3.0,
      -4.0
    );

    renderer.render(scene, camera);
  }

  try {
    stage.classList.add("is-ready");
    const fallback = document.getElementById("model-fallback");
    if (fallback) fallback.style.display = "none";
    animate();
  } catch (error) {
    console.error("Cassette model render failed", error);
    stage.classList.add("is-fallback");
  }

  document.addEventListener("visibilitychange", () => {
    if (!document.hidden && !frameId) animate();
  });
})();
